{"command":"tmp=$(mktemp -d); hf=$tmp/h; printf '1.1.1.1 a\n' >$hf; ./executable --host-file "$hf" --quiet list --raw >$tmp/raw; python3 - <<'PY' "$tmp/raw"
import sys
b=open(sys.argv[1],'rb').read()
print(repr(b))
for line in b.splitlines(True): print(list(line), repr(line))
PY"}

{"command":"tmp=$(mktemp -d); pf=$tmp/p; pf2=$tmp/p2; printf '1.1.1.1 a b\n2.2.2.2 c\n' >$pf; printf '3.3.3.3 d\n' >$pf2;
runpair(){ label="$1"; shift; hf1=$tmp/o_$label; hf2=$tmp/n_$label; printf '127.0.0.1 localhost\n10.0.0.1 def2 alias\n' >$hf1; cp $hf1 $hf2; for cmd in "$@"; do eval ./executable --host-file "$hf1" $cmd >$tmp/oo 2>&1; r1=$?; eval python3 hostctl.py --host-file "$hf2" $cmd >$tmp/nn 2>&1; r2=$?; sed "s#$hf1#HOST#g;s#$hf2#HOST#g" $tmp/oo >$tmp/ooN; sed "s#$hf1#HOST#g;s#$hf2#HOST#g" $tmp/nn >$tmp/nnN; if [ $r1 -ne $r2 ] || ! diff -u $tmp/ooN $tmp/nnN >/tmp/diffout; then echo "### DIFF $label :: $cmd rc $r1/$r2"; cat /tmp/diffout; echo 'filediff'; diff -u $hf1 $hf2 || true; fi; done; }
runpair basic "add p -f $pf" "list" "list -o markdown" "status" "disable p" "list --raw" "enable p -o json" "add domains p x y --ip 5.5.5.5" "remove domains p x" "replace p -f $pf2" "remove p" 
# Error comparisons
hf=$tmp/h; printf '' >$hf; for cmd in "add" "add p" "remove --all" "backup extra" "list -o xml" "unknown" "list --version" "-z"; do echo "### err $cmd"; ./executable --host-file $hf $cmd >$tmp/oo 2>&1; r1=$?; python3 hostctl.py --host-file $hf $cmd >$tmp/nn 2>&1; r2=$?; echo rc=$r1/$r2; diff -u $tmp/oo $tmp/nn || true; done"}

{"command":"tmp=$(mktemp -d); pf=$tmp/p; printf '1.1.1.1 a\n' >$pf; hf1=$tmp/oh; hf2=$tmp/nh; printf '127.0.0.1 localhost\n' >$hf1; cp $hf1 $hf2; ./executable --host-file $hf1 add p -f $pf >/dev/null; python3 hostctl.py --host-file $hf2 add p -f $pf >/dev/null; ./executable --host-file $hf1 disable p >/dev/null; python3 hostctl.py --host-file $hf2 disable p >/dev/null;
for cmd in "list -c domain,ip,status,profile" "list --column IP,Host" "status -c status,profile" "list p -o json" "list nope -o json" "enable --all" "disable --only p" "--quiet enable p" "add domains p b -o json" "remove domains p b -o json"; do echo "### $cmd"; eval ./executable --host-file "$hf1" $cmd >$tmp/oo 2>&1; r1=$?; eval python3 hostctl.py --host-file "$hf2" $cmd >$tmp/nn 2>&1; r2=$?; sed "s#$hf1#HOST#g;s#$hf2#HOST#g" $tmp/oo >$tmp/ooN; sed "s#$hf1#HOST#g;s#$hf2#HOST#g" $tmp/nn >$tmp/nnN; echo rc=$r1/$r2; diff -u $tmp/ooN $tmp/nnN || true; diff -u $hf1 $hf2 || true; done
# backup/restore with normalized temp dir
b1=$tmp/b1; b2=$tmp/b2; mkdir $b1 $b2; echo '### backup'; ./executable --host-file $hf1 backup --path $b1 >$tmp/bo 2>&1; python3 hostctl.py --host-file $hf2 backup --path $b2 >$tmp/bn 2>&1; sed "s#$hf1#HOST#g;s#$hf2#HOST#g;s#$b1#BPATH#g;s#$b2#BPATH#g" $tmp/bo >$tmp/boN; sed "s#$hf1#HOST#g;s#$hf2#HOST#g;s#$b1#BPATH#g;s#$b2#BPATH#g" $tmp/bn >$tmp/bnN; diff -u $tmp/boN $tmp/bnN || true
# sync errors
for cmd in "sync" "sync docker" "sync docker p" "sync docker p q" "sync docker-compose p --compose-file missing.yml"; do echo "### $cmd"; ./executable --host-file $hf1 $cmd >$tmp/so 2>&1; r1=$?; python3 hostctl.py --host-file $hf2 $cmd >$tmp/sn 2>&1; r2=$?; sed "s#$hf1#HOST#g;s#$hf2#HOST#g" $tmp/so >$tmp/soN; sed "s#$hf1#HOST#g;s#$hf2#HOST#g" $tmp/sn >$tmp/snN; echo rc=$r1/$r2; diff -u $tmp/soN $tmp/snN || true; done"}
